12	export class MockClaudeCodeSdkService implements IClaudeCodeSdkService {
13		readonly _serviceBrand: undefined;
14		public queryCallCount = 0;
15		public setModelCallCount = 0;
16		public lastSetModel: string | undefined;
17		public setPermissionModeCallCount = 0;
18		public lastSetPermissionMode: string | undefined;
19		public lastQueryOptions: Options | undefined;
