21	
22		public mockSessions: SDKSessionInfo[] = [];
23		public mockSessionMessages: SessionMessage[] = [];
24		public mockSubagentIds: string[] = [];
25		public mockSubagentMessages: Map<string, SessionMessage[]> = new Map();
