73		private createMockQuery(prompt: AsyncIterable<SDKUserMessage>): Query {
74			const generator = this.createMockGenerator(prompt);
75			return {
76				[Symbol.asyncIterator]: () => generator,
77				setModel: async (modelId: string) => {
78					this.setModelCallCount++;
79					this.lastSetModel = modelId;
80				},
81				setPermissionMode: async (mode: string) => {
82					this.setPermissionModeCallCount++;
83					this.lastSetPermissionMode = mode;
84				},
85				abort: () => { /* no-op for mock */ },
86			} as unknown as Query;
87		}
88	
89		private async* createMockGenerator(prompt: AsyncIterable<SDKUserMessage>): AsyncGenerator<SDKAssistantMessage | SDKResultMessage, void, unknown> {
90			// For every user message yielded, emit an assistant text and then a result
91			for await (const msg of prompt) {
92				this.receivedMessages.push(msg);
93				yield {
94					type: 'assistant',
95					session_id: 'sess-1',
96					message: {
97						role: 'assistant',
98						content: [
99							{ type: 'text', text: 'Hello from mock!' }
100						]
101					}
102				} as SDKAssistantMessage;
103				yield {
104					type: 'result',
105					subtype: 'error_max_turns',
106					uuid: 'mock-uuid',
107					session_id: 'sess-1',
108					duration_ms: 0,
109					duration_api_ms: 0,
110					is_error: false,
111					num_turns: 0,
112					total_cost_usd: 0,
113					usage: { input_tokens: 0, output_tokens: 0 },
114					permission_denials: []
115				} as unknown as SDKResultMessage;
116			}
117		}
118	}
