/**
 * Tool names that spawn subagents and can therefore act as the parent of a subagent
 * session. Both the legacy `Task` tool and the renamed `Agent` tool are supported.
 */
function isSubagentParentTool(name: string): boolean {
	return name === ClaudeToolNames.Agent || name === ClaudeToolNames.Task;
}

/**
